window.NPC_CHUNK_154 = [{"name":"Jeshura","cr":14,"xp":38400,"race":"pairaka div","gender":"Female","age_category":"Adult","classes":[{"class":"arcane archer","level":4},{"class":"sorcerer","level":6}],"alignment":"NE","size":"Medium","type":"outsider","sub_types":["div","evil","extraplanar","shapechanger"],"init":6,"senses":["darkvision 60 ft.","detect good","detect magic","see in darkness"],"ac":26,"ac_touch":18,"ac_flat_footed":19,"ac_mods":"+1 deflection, +6 Dex, +1 dodge, +8 natural","hp":212,"hd":"13d10+6d6+120","hd_value":19,"fort":13,"ref":16,"will":16,"save_mods":"+4 vs. nausea effects","defensive_abilities":["accustomed to awfulness"],"dr":"10/cold iron or good","immunities":["disease","fire","poison","sickened"],"resists":["acid 10","electricity 10"],"sr":22,"speed":[{"type":"fly","speed":50,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"2 claws +20 (1d6+4 plus disease)","ranged":"+4 composite longbow +27 (1d8+8/19-20/x3 plus disease and 1d6 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"enhance arrows","details":"elemental, magic"},{"type":"imbue arrow"},{"type":"infected arrows"},{"type":"lustful dreams"},{"type":"seeker arrow"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"charm monster"},{"spell":"dimension door","details":"self plus 50 lbs. of objects only"},{"spell":"misdirection"}]},{"frequency":"1/day","spells":[{"spell":"insect plague"},{"spell":"summon div","details":"1d4 dorus 50%, level 3"}]},{"frequency":"12/day","spells":[{"spell":"plague's caress"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":9,"spellsknown_concentration":18,"spellsknown":[{"spell_level":4,"spell_slots":6,"spells":[{"spell":"black tentacles"},{"spell":"contagion"}]},{"spell_level":3,"spell_slots":8,"spells":[{"spell":"dispel magic"},{"spell":"fireball"},{"spell":"slow"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"darkness"},{"spell":"glitterdust"},{"spell":"mirror image"},{"spell":"summon swarm"},{"spell":"web"}]},{"spell_level":1,"spell_slots":9,"spells":[{"spell":"burning hands"},{"spell":"charm animal"},{"spell":"gravity bow"},{"spell":"mage armor"},{"spell":"ray of enfeeblement"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"touch of fatigue"}]}],"bloodline":"Pestilence","strength":19,"dexterity":22,"constitution":22,"intelligence":12,"wisdom":18,"charisma":28,"baseatk":16,"cmb":20,"cmd":38,"feats":[{"feat":"Arcane Strike"},{"feat":"Bleeding Critical"},{"feat":"Critical Focus"},{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Eschew Materials"},{"feat":"Improved Critical (composite longbow)"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Weapon Focus (composite longbow)"}],"skills":[{"skill":"Bluff","value":31},{"skill":"Disguise","value":28},{"skill":"Fly","value":19},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":26},{"skill":"Spellcraft","value":23}],"languages":["Abyssal","Celestial","Infernal","telepathy 100 ft."],"sq":["change shape (any Small or Medium animal or humanoid; polymorph)"],"special_abilities":[{"type":"Accustomed to Awfulness","kind":"Ex","details":"Jeshura is immune to the sickened condition and gains a +4 bonus on all saving throws against effects that cause nausea or disease."},{"type":"Infected Arrows","kind":"Su","details":"Any arrows Jeshura fires carry with them bubonic plague, similarly to her claw attacks. Pestilence Bloodline This rare sorcerer bloodline was first detailed on page 29 of Pathfinder Adventure Path #29. It grants Heal as a bonus class skill, and Jeshura's level is high enough that she gains charm animal and summon swarm as bonus spells. Vermin are susceptible to her mind-affecting spells, and are treated as animals for the purposes of determining which mind-affecting spells can affect them."},{"type":"Plague's Caress","kind":"Sp","details":"Jeshura can make a melee touch attack as a standard action that causes a living creature's flesh to break out into rancid-smelling pustules and sores for 3 rounds. These sores cause the victim to become sickened for these 3 rounds-this is a disease effect."}],"gear":"+4 composite longbow, ring of protection +1","during_combat":"Jeshura has no time to prepare for combat initially, so she casts mirror image on the first round of battle to get herself some time to cast mage armor and gravity bow before she begins firing her longbow at foes. If she's surrounded, she tries to sow confusion by using darkness or glitterdust to make it even more difficult for her enemies to see. If reduced to fewer than 120 hit points, Jeshura attempts to flee via dimension door-this, of course, likely results in her being redirected by the vault's teleport trap into another prison, area H8.","morale":"If reduced to 30 or fewer hit points and prevented from attempting to escape by dimension door, Jeshura does something that may surprise the PCs-she drops to her knees and begs for mercy. Although she has the powers and shape of a pairaka div, she remains a Human at heart and still fears death. See Development, below, for what comes of granting mercy to the Plague Queen of Kho.","source":"AP 83, Pathfinder RPG Bestiary 3 88"},{"name":"Great Ghul","cr":10,"xp":9600,"race":"ghul","age_category":"Adult","alignment":"CE","size":"Medium","type":"undead","sub_types":["shapechanger"],"init":9,"senses":["darkvision 60 ft."],"ac":24,"ac_touch":16,"ac_flat_footed":18,"ac_mods":"+5 Dex, +1 dodge, +8 natural","hp":138,"hd":"12d8+84","hd_value":12,"fort":10,"ref":11,"will":12,"dr":"10/cold iron and good","immunities":["undead traits"],"resists":["fire 10"],"speed":[{"type":"climb","speed":20},{"type":"land","speed":40}],"melee":"bite +17 (1d6+8), 2 claws +17 (1d4+8/19-20 plus bleed)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed 1"},{"type":"create spawn"},{"type":"cursed claws"},{"type":"rend","details":"2 claws, 1d6+8"},{"type":"warp metal"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"greater invisibility","details":"self only"}]}],"strength":26,"dexterity":20,"intelligence":18,"wisdom":19,"charisma":22,"baseatk":9,"cmb":17,"cmd":33,"feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":18},{"skill":"Climb","value":31},{"skill":"Disguise","value":21},{"skill":"Intimidate","value":21},{"skill":"Perception","value":19},{"skill":"Sense Motive","value":19},{"skill":"Stealth","value":20},{"skill":"Survival","value":16}],"languages":["Abyssal","Ancient Osiriani","Necril","Terran"],"sq":["change shape (any humanoid, ghul, or hyena; doesn't detect as undead in living forms; polymorph)","genie-kin"],"special_abilities":[{"type":"Create Spawn","kind":"Su","details":"Any humanoid slain by a great ghul becomes a ghoul on the next moonrise. Likewise, a slain janni becomes a ghul and a slain genie becomes a great ghul. Blessing or destroying the body (such as with acid or fire) prevents this reanimation."},{"type":"Cursed Claws","kind":"Ex","details":"A great ghul's claws count as both cold iron and magic for the purpose of bypassing damage reduction."},{"type":"Genie-Kin","kind":"Ex","details":"For all race-related effects (such as a ranger's favored enemy), a great ghul is considered a genie (and thus a chaotic outsider and an evil outsider) even though its type is undead."},{"type":"Warp Metal","kind":"Su","details":"As a standard action, a great ghul may warp and deform any one metal object within 20 feet. This functions like warp wood, but affects only metal objects that fail a DC 22 Fortitude save. Armor or shields lose half their bonus to AC (enhancement bonuses are unaffected), and weapons are rendered useless except as improvised clubs. Other objects, such as doors, are rendered useless for their function. The transformation lasts 1 minute, after which the affected metal reverts to its normal state. The save DC is Charisma-based."}],"during_combat":"The great ghuls cast greater invisibility on themselves on the first round of combat, then move forward to attack foes. They prefer to fight divine spellcasters first, teaming up on foes like clerics or paladins in an attempt to deny the PCs healing while simultaneously taking out the PCs who pose the greatest threat to them.","morale":"The great ghuls fight until destroyed.","source":"AP 83, Pathfinder RPG Bestiary 3 125, Pathfinder Campaign Setting: Dark Markets, A Guide to Katapesh 63"},{"name":"Agazuberi","cr":15,"xp":51200,"race":"black jinni","gender":"Female","age_category":"Adult","alignment":"CE","size":"Large","type":"outsider","sub_types":["chaotic","evil","extraplanar"],"init":10,"senses":["darkvision 60 ft."],"ac":30,"ac_touch":16,"ac_flat_footed":23,"ac_mods":"+6 Dex, +1 dodge, +14 natural, -1 size","hp":230,"hd":"20d10+120","hd_value":20,"fort":18,"ref":18,"will":10,"defensive_abilities":["freedom of movement","obscuring cloud"],"immunities":["electricity","fire"],"weaknesses":["vulnerability to recitation"],"speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":40}],"melee":"+1 conductive falchion +29 (2d6+13/15-20 plus 1d10 electricity), gore +22 (2d8+4) or 2 claws +27 (2d6+8), gore +27 (2d8+8)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"create spawn"},{"type":"dust vortex"},{"type":"shocking touch"}],"strength":26,"dexterity":22,"constitution":23,"intelligence":12,"wisdom":15,"charisma":18,"baseatk":20,"cmb":29,"cmd":46,"feats":[{"feat":"Bleeding Critical"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Improved Critical (falchion)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Weapon Focus (falchion)"}],"skills":[{"skill":"Acrobatics","value":29},{"skill":"Bluff","value":27},{"skill":"Fly","value":4},{"skill":"Intimidate","value":27},{"skill":"Knowledge (religion)","value":24},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":25},{"skill":"Stealth","value":25,"special":"+8 in storms or clouds"}],"languages":["Ancient Osiriani","Aquan","Auran","Ignan","Terran"],"sq":["aligned weapons","stormwalk"],"special_abilities":[{"type":"Aligned Weapons","kind":"Su","details":"A black jinni's natural weapons and any weapon she wields are treated as chaotic and evil for the purposes of overcoming damage reduction."},{"type":"Create Spawn","kind":"Su","details":"A humanoid or genie slain by a black jinni's melee attacks enhanced by her shocking touch rises 1d4 rounds later as an undead spawn. Humans rise as zombies, jann rise as ghuls (Pathfinder RPG Bestiary 3 125), and djinn, efreet, shaitans, and marids rise as great ghuls. Any spawn created by a black jinni are under her control."},{"type":"Dust Vortex","kind":"Su","details":"Once per day, as a full-round action, a black jinni can cause the obscuring cloud that surrounds her to become a vortex of electrically charged dust. This vortex is 20 ft. high and radiates to a range of 30 feet, with the black jinni at the vortex's center. The winds within this area are considered a windstorm (Core Rulebook 439). Creatures within the vortex that would normally be blown away are instead drawn toward the center to a square adjacent to the black jinni. A creature that ends its turn within the dust vortex takes 10d6 points of electricity damage (Reflex DC 23 half). Once the dust vortex is created, it remains stationary, allowing the black jinni to move around in it or even leave it. The vortex remains in place for 1d6 rounds, or until the black jinni dismisses it as a move action. The save DC is Constitution-based."},{"type":"Obscuring Cloud","kind":"Ex","details":"A black jinni is continually surrounded by a cloud of obscuring dust and scouring wind. This cloud gives her a +8 racial bonus on Stealth checks while within a sandstorm or other area of blowing dust. In addition, a black jinni has concealment (20% miss chance) while the cloud is in effect. Any strong (or stronger) wind can suppress the obscuring cloud as long as the wind persists."},{"type":"Shocking Touch","kind":"Su","details":"Any creature hit by a black jinni's claw attack or its conductive falchion takes an additional 1d10 points of electricity damage-on a critical hit, this additional electricity damage increases to 2d10 points of damage and the creature must succeed at a DC 23 Fortitude save or the electricity lingers on its body, dealing an additional 1d10 points of electricity damage each round on the start of the victim's turn for 1d6 additional rounds. Immersion in any liquid ends this ongoing damage, as does contact with a metal object of at least Medium or larger size that is in contact with the ground. The save DC is Constitution-based."},{"type":"Stormwalk","kind":"Ex","details":"A black jinni is able to move about in any storm of natural or unnatural origin of hurricane velocity or less without suffering any of its effects."},{"type":"Vulnerability to Recitation","kind":"Ex","details":"As cursed genies of evil and chaos, black jinn are strangely susceptible to recitations of certain holy tracts belonging to good or lawful deities or philosophies. These include the spells dictum and holy word, but also forceful recitations of nonmagical holy sermonizing. If a cleric or paladin of a lawful or good deity succeeds at an opposed Knowledge (religion) check against a black jinni's Knowledge (religion) check as a standard action, the black jinni must succeed at a DC 20 Fortitude save or be instantly destroyed, leaving behind only a small spot of charred ash. If this save is successful, the black jinni instead takes 5d6 points of damage. Unlike most black jinn, though, Agazuberi is particularly patient and accepting of such recitations-she gains a +4 bonus on her Fortitude saves and Knowledge (religion) checks when reacting to this weakness."}],"gear":"+1 conductive falchion, ring of freedom of movement, gem encrusted gold pectoral necklace worth 10,000 gp","during_combat":"Agazuberi prefers to avoid creating her dust vortex so that she can focus on moving about the room and take advantage of Spring Attack and Mobility. She's patient and would prefer to deny her enemies opportunities for full attacks anyway, believing that extending her time in battle will give her greater opportunities to spread out the pain and suffering she hopes to inflict to alleviate her boredom. If reduced to fewer than 120 hit points, though, her base nature begins to take over and she grows more feral and violent, activating her dust vortex in the center of the room to fill the entire area before focusing her attacks on the most wounded foes, now attempting to set up full attacks against her enemies in order to finish them off.","morale":"Agazuberi fights to the death.","source":"AP 83, Pathfinder Adventure Path #23 82"},{"name":"Stone Minion","cr":8,"xp":4800,"race":"Animated stone maidens","age_category":"Adult","alignment":"N","size":"Medium","type":"outsider","sub_types":["earth","elemental","extraplanar"],"init":4,"senses":["darkvision 60 ft."],"ac":20,"ac_touch":10,"ac_flat_footed":20,"ac_mods":"+10 natural","hp":95,"hd":"10d10+40","hd_value":10,"fort":11,"ref":5,"will":12,"defensive_abilities":["one with the earth"],"dr":"10/ magic","immunities":["earth magic","elemental traits"],"speed":[{"type":"burrow","speed":30},{"type":"land","speed":30}],"melee":"+1 scimitar +17 (1d8+6/18- 20), slam +10 (1d8+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"earth mastery"}],"strength":20,"dexterity":10,"constitution":18,"intelligence":15,"wisdom":16,"charisma":20,"baseatk":10,"cmb":15,"cmd":25,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Weapon Focus (scimitar)"}],"skills":[{"skill":"Craft (stonemasonry)","value":15},{"skill":"Diplomacy","value":18},{"skill":"Knowledge (dungeoneering)","value":15},{"skill":"Knowledge (nature)","value":15},{"skill":"Knowledge (planes)","value":15},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":16},{"skill":"Survival","value":16}],"languages":["Common","Terran"],"special_abilities":[{"type":"Earth Mastery","kind":"Ex","details":"A stone minion gains a +1 bonus on attack and damage rolls if both she and her foe are touching the ground. If an opponent is airborne or waterborne, the stone minion takes a -4 penalty on attack and damage rolls."},{"type":"Immunity to Earth Magic","kind":"Ex","details":"A stone minion is immune to all spells and spell-like abilities with the earth descriptor, including spells of the Earth domain. She is also immune to the supernatural abilities of creatures with the Earth subtype."},{"type":"One with the Earth","kind":"Ex","details":"A stone minion is so closely tied to the earth that any damage she takes from the natural attacks of a creature with the Earth subtype or a creature made primarily from stone or earth (such as a stone golem or clay golem) is treated as nonlethal damage."}],"gear":"+1 scimitar","during_combat":"Both of these animated minions move to attack anyone they believe is attempting to enter the foyer, but make no hostile moves until then or until they are attacked. They always fight with Power Attacks unless they consistently miss with their weapons.","morale":"The stone minions fight until slain.","source":"AP 83, Tome of Horrors Complete 572"},{"name":"Aiveria","cr":14,"xp":38400,"race":"stone maiden","gender":"Female","age_category":"Adult","classes":[{"class":"bard","level":10}],"alignment":"N","size":"Medium","type":"outsider","sub_types":["earth","elemental","extraplanar"],"init":7,"senses":["darkvision 60 ft."],"ac":31,"ac_touch":14,"ac_flat_footed":27,"ac_mods":"+7 armor, +3 Dex, +1 dodge, +10 natural","hp":210,"hd":"10d10+10d8+110","hd_value":20,"fort":15,"ref":15,"will":19,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic","defensive_abilities":["one with the earth"],"dr":"10/magic","immunities":["earth magic","elemental traits"],"weaknesses":["veil"],"speed":[{"type":"burrow","speed":30},{"type":"land","speed":30}],"melee":"+2 keen scimitar +26 (1d6+11/15-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"animate rocks"},{"type":"bardic performance","details":"30 rounds/day; move action; countersong, dirge of doom [DC 23], distraction, fascinate [DC 23], inspire competence +3, inspire courage +2, inspire greatness, suggestion [DC 23]"},{"type":"earth mastery"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"magic stone"},{"spell":"meld into stone"},{"spell":"soften earth and stone"},{"spell":"spike stones"},{"spell":"stone shape"},{"spell":"stone tell"},{"spell":"transmute mud to rock"},{"spell":"transmute rock to mud"}]},{"frequency":"1/day","spells":[{"spell":"iron body"},{"spell":"wall of stone"}]},{"frequency":"3/day","spells":[{"spell":"move earth"}]}],"spellsknown_caster":"bard","spellsknown_caster_level":10,"spellsknown_concentration":18,"spellsknown":[{"spell_level":4,"spell_slots":3,"spells":[{"spell":"dimension door"},{"spell":"hold monster"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"confusion"},{"spell":"cure serious wounds"},{"spell":"haste"},{"spell":"slow"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"blindness/deafness"},{"spell":"invisibility"},{"spell":"mirror image"},{"spell":"sound burst"},{"spell":"suggestion"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"charm person"},{"spell":"cure light wounds"},{"spell":"feather fall"},{"spell":"grease"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"message"},{"spell":"prestidigitation"}]}],"strength":22,"dexterity":16,"constitution":20,"intelligence":13,"wisdom":16,"charisma":26,"baseatk":17,"cmb":23,"cmd":37,"feats":[{"feat":"Arcane Strike"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Spring Attack"},{"feat":"Weapon Focus (scimitar)"}],"skills":[{"skill":"Acrobatics","value":26},{"skill":"Knowledge (arcana)","value":24},{"skill":"Knowledge (planes)","value":24},{"skill":"Perform (act)","value":31},{"skill":"Perform (oratory)","value":31},{"skill":"Perform (sing)","value":21},{"skill":"Spellcraft","value":24},{"skill":"Stealth","value":26}],"languages":["Common","Terran"],"sq":["bardic knowledge +5","jack-of-all-trades (use any skill)","lore master 1/day","stone glide","versatile performance (act, oratory, sing)"],"special_abilities":[{"type":"Animate Rocks","kind":"Su","details":"A stone maiden can animate rocks within 180 ft. at will, controlling up to two rocks at a time. These animated rocks are posted as guardians in area J1."},{"type":"Earth Mastery","kind":"Ex","details":"A stone maiden gains a +1 bonus on attack and damage rolls if both she and her foe are touching the ground. If an opponent is airborne or waterborne, the stone maiden takes a -4 penalty on attack and damage rolls."},{"type":"Immunity to Earth Magic","kind":"Ex","details":"A stone maiden is immune to all spells and spell-like abilities with the earth descriptor, including spells of the Earth domain. She is also immune to the supernatural abilities of creatures that possess the Earth subtype."},{"type":"One with the Earth","kind":"Ex","details":"A stone maiden is so closely tied with the earth that any damage she takes from the natural attacks of a creature with the Earth subtype or a creature made primarily from stone or earth (such as a stone golem or clay golem) is treated as nonlethal damage."},{"type":"Stone Glide","kind":"Su","details":"This functions as the earth elemental's earth glide ability, except the stone maiden can move through stone, dirt, crystal, and metal."},{"type":"Veil","kind":"Su","details":"Each stone maiden is mystically bound to her veil and never lets it out of her possession. If she is ever more than 1,000 ft. from it, she takes a -4 penalty to Strength, Dexterity, and Constitution, and dies within 4d6 hours, crumbling to dust. If her veil is destroyed (hardness 3, hp 10), she dies in 1 minute. A stone maiden's veil doesn't radiate magic."}],"gear":"+3 mithral glamered chain shirt, +2 keen scimitar","source":"AP 83, Tome of Horrors Complete 572"},{"name":"Isatemkhebet","cr":14,"xp":38400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":14}],"alignment":"LE","size":"Medium","type":"undead","sub_types":["augmented humanoid","human"],"templates_applied":"mummified","init":2,"senses":["darkvision 60 ft."],"auras":["command (60 ft., DC 23)","frightful presence (30 ft., DC 16, 1d6 rounds)"],"ac":28,"ac_touch":12,"ac_flat_footed":26,"ac_mods":"+7 armor, +2 Dex, +4 natural, +5 shield","hp":221,"hd":"14d10+140","hd_value":14,"fort":17,"ref":10,"will":7,"save_mods":"+4 vs. electricity, weather, and wind effects, Will: +4 vs. fear","defensive_abilities":["bravery +4"],"dr":"5/-","immunities":["undead traits"],"weaknesses":["vulnerable to acid"],"speed":[{"type":"land","speed":20}],"melee":"+2 khopesh +23 (1d8+15/17-20), +2 heavy shield +24 (1d8+10 plus bull rush)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burst of vengeance"},{"type":"dust stroke"},{"type":"weapon training","details":"heavy blades +3, close +2, bows +1"}],"strength":18,"dexterity":15,"intelligence":8,"wisdom":8,"charisma":22,"baseatk":14,"cmb":20,"cmd":32,"feats":[{"feat":"Double Slice"},{"feat":"Exotic Weapon Proficiency (khopesh)"},{"feat":"Greater Shield Focus"},{"feat":"Greater Weapon Focus (khopesh)"},{"feat":"Greater Weapon Specialization (khopesh)"},{"feat":"Improved Critical (khopesh)"},{"feat":"Improved Shield Bash"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Shield Focus"},{"feat":"Shield Master"},{"feat":"Shield Slam"},{"feat":"Toughness"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (khopesh)"},{"feat":"Weapon Specialization (khopesh)"}],"skills":[{"skill":"Intimidate","value":17},{"skill":"Knowledge (history)","value":4},{"skill":"Linguistics","value":1},{"skill":"Perception","value":7},{"skill":"Ride","value":8}],"languages":["Ancient Osiriani","Auran","Necril"],"sq":["armor training 3"],"special_abilities":[{"type":"Aura of Command","kind":"Su","details":"As long as her statue in area A4 of the Five-Pointed Sun remains intact, Isatemkhebet possesses an aura of command. All creatures within 60 ft. become convinced that Isatemkhebet is a powerful general and feel compelled to follow her orders. Once per round as a swift action, Isatemkhebet can issue a command to any one creature within this area. The targeted creature can resist the compulsion to follow the command (which has the same limitations as a suggestion at CL 14th) with a successful DC 23 Will save. A successful save grants immunity to Isatemkhebet's aura of command for 24 hours. This is a language-dependent, mind-affecting effect. Undead who have fewer than 14 Hit Dice can be affected by Isatemkhebet's aura of command as if they weren't immune to mind-affecting effects. The save DC is Charisma-based."}],"gear":"skyplate armor (+1 steel lamellar), +1 bashing heavy steel shield, +2 khopesh, headband of alluring charisma +4, bracelet of friends (1 charm, currently linked to Kor-Ahn-Tuk)","before_combat":"If she fears that she is about to be attacked, Isatemkhebet uses her bracelet of friends to call her mummified gorgon, Kor-Ahn-Tuk, from area A13 to her side; if she's surprised, she does this on the first round of combat instead. If the gorgon has already been defeated, she wastes her action attempting to call it, but this doesn't expend the bracelet's last charm.","during_combat":"At her first two opportunities to make a full attack, Isatemkhebet activates her burst of vengeance ability. She prefers to leave victims alive but disabled, so that after a fight she can leisurely finish them off with a slam attack and her dust stroke ability, although she doesn't generally take advantage of this tactic in battle. Each round, she attempts to use her aura of command-speaking in Ancient Osiriani-to order one PC at a time to lay down his weapons, drop to his knees, and take no action. She prefers to attack characters obviously capable of healing or those who provide support to allies first, but if faced with a foe that is particularly capable of damaging her, she concentrates on that target instead. She uses Power Attack until she misses with more than half her attacks made as     a full-attack action, at which point she ceases using Power Attack against that foe.","morale":"Isatemkhebet is eager to prove her worth to the Sky Pharaoh, and has little interest in surrender, but if the PCs reduce her to 50 or fewer hit points, she attempts to return to her sarcophagus and lower the lid so that she can gain its healing effects. Once she's exhausted her sarcophagus's power for the day, she rises again and rejoins the fight until destroyed.","source":"AP 83, Pathfinder RPG Bestiary 4 196"},{"name":"Tef-Naju","cr":17,"xp":102400,"race":"shaitan","gender":"Male","age_category":"Adult","classes":[{"class":"magus","level":13}],"alignment":"LN","size":"Large","type":"outsider","sub_types":["earth","extraplanar"],"init":6,"senses":["darkvision 60 ft.","tremorsense 60 ft."],"ac":34,"ac_touch":10,"ac_flat_footed":33,"ac_mods":"+10 armor, +1 Dex, +10 natural, +4 shield, -1 size","hp":296,"hd":"9d10+13d8+189","hd_value":22,"fort":22,"ref":11,"will":16,"dr":"10/adamantine (120 points)","immunities":["electricity"],"speed":[{"type":"burrow","speed":60},{"type":"climb","speed":20},{"type":"land","speed":15}],"melee":"axe of the imperative +28 (2d6+10/19-20/x3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"earth mastery"},{"type":"improved spell combat"},{"type":"metalmorph"},{"type":"spell combat","details":"-2 attack, +2 concentration"},{"type":"spellstrike"},{"type":"stone curse"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"meld into stone"},{"spell":"plane shift","details":"or Material Plane only, Astral Plane, to Elemental Planes, save himself, willing targets"},{"spell":"soften earth and stone"},{"spell":"stone shape"},{"spell":"veil","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"transmute mud to rock"},{"spell":"transmute rock to mud"}]},{"frequency":"3/day","spells":[{"spell":"quickened glitterdust"},{"spell":"rusting grasp"},{"spell":"stone tell"},{"spell":"stoneskin"},{"spell":"wall of stone"}]}],"spellsprepared_caster":"magus","spellsprepared_caster_level":13,"spellsprepared_concentration":18,"spellsprepared":[{"spell_level":5,"spell_slots":2,"spells":[{"spell":"acidic spray"},{"spell":"telekinesis"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"detonate"},{"spell":"dimension door"},{"spell":"mass reduce person"},{"spell":"shout"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"dispel magic"},{"spell":"fireball"},{"spell":"force punch"},{"spell":"haste"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"bear's endurance"},{"spell":"defensive shock"},{"spell":"invisibility"},{"spell":"mirror image"},{"spell":"scorching ray"},{"spell":"stone call"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"chill touch"},{"spell":"corrosive touch"},{"spell":"magic missile","count":2},{"spell":"ray of enfeeblement"},{"spell":"shield"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":28,"dexterity":15,"constitution":26,"intelligence":20,"wisdom":14,"charisma":13,"baseatk":18,"cmb":28,"cmb_special":"+32 bull rush","cmd":40,"cmd_special":"42 vs. bull rush","feats":[{"feat":"Arcane Strike"},{"feat":"Combat Casting"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Greater Bull Rush"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (battleaxe)"},{"feat":"Improved Initiative"},{"feat":"Improved Lightning Reflexes"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (glitterdust)"},{"feat":"Weapon Focus (battleaxe)"}],"skills":[{"skill":"Acrobatics","value":19},{"skill":"Climb","value":12},{"skill":"Intimidate","value":26},{"skill":"Knowledge (arcana)","value":28},{"skill":"Knowledge (engineering)","value":25},{"skill":"Knowledge (planes)","value":28},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":27},{"skill":"Spellcraft","value":28},{"skill":"Stealth","value":18}],"languages":["Ancient Osiriani","Aquan","Auran","Ignan","Terran","telepathy 100 ft."],"sq":["arcane pool (11 points, +4)","fighter training (fighter level 6)","heavy armor proficiency","improved spell recall","knowledge pool","magus arcana (concentrate, empowered magic, maneuver mastery [bull rush], maximized magic)","stone glide"],"gear":"+1 full plate, axe of the imperative (+1 battleaxe), belt of giant strength +4, ring of x-ray vision, potions of cure serious wounds (2), scrolls of flesh to stone (2), scrolls of stone to flesh (2), wand of lightning bolt (CL 10th, 14 charges), holy water (4), unholy water (4)","before_combat":"Before he engages in combat, Tef-Naju casts stoneskin, bear's endurance, and shield on himself.","during_combat":"Tef-Naju prefers to fight in melee combat, combining his skill at arms with casting melee-based spells in battle, yet he prefers to avoid putting himself in situations where he's outnumbered or surrounded. Tef-Naju generally spends the first few rounds of combat establishing control of the battlefield, starting by casting invisibility on himself and then remaining mobile while using spells like mass reduce person, telekinesis, transmute rock to mud, or wall of stone, to disarm foes at range. If Tef-Naju finds himself surrounded, he uses detonate to deal electricity damage, since he's immune to this effect. Once in melee, Tef-Naju casts mirror image, followed the next round by haste.","morale":"If reduced to fewer than 30 hit points, Tef-Naju flees combat (preferably by simply stone gliding into the ground), whereupon he flees to his bastion (area J) to recover from the battle as swiftly as possible (likely with the aid of healing magic cast by his lover, Aiveria), hoping to return to the scene of the attack to continue the fight if intruders still threaten the Slave Trenches.","source":"AP 83, Pathfinder RPG Bestiary 143, Pathfinder RPG Ultimate Magic 9"},{"name":"Tainted Chaos Beast","cr":12,"xp":19200,"race":"chaos beast","age_category":"Adult","alignment":"CE","size":"Large","type":"outsider","sub_types":["chaotic","extraplanar"],"templates_applied":"advanced","init":7,"senses":["darkvision 60 ft."],"ac":24,"ac_touch":13,"ac_flat_footed":20,"ac_mods":"+3 Dex, +1 dodge, +11 natural, -1 size","hp":162,"hd":"12d10+96","hd_value":12,"fort":15,"ref":11,"will":7,"defensive_abilities":["amorphous","resistant to transformation"],"dr":"10/good","sr":23,"speed":[{"type":"fly","speed":70,"maneuverability":"poor"},{"type":"land","speed":20}],"melee":"4 claw +21 (1d8+9 plus corporeal instability)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"corporeal instability","details":"DC 23"}],"strength":29,"dexterity":17,"constitution":24,"intelligence":14,"wisdom":16,"charisma":15,"baseatk":12,"cmb":22,"cmd":36,"cmd_special":"can't be tripped","feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Toughness"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":18,"special":"-4 when jumping"},{"skill":"Climb","value":24},{"skill":"Fly","value":12},{"skill":"Intimidate","value":14},{"skill":"Perception","value":18},{"skill":"Stealth","value":14},{"skill":"Survival","value":15},{"skill":"Swim","value":24}],"sq":["freeze"],"during_combat":"After 3 rounds, the bizarre creatures complete their transformations, unfurling their concealed, misshapen wings before attacking. The chaos beats focus on separate targets if possible, swooping in for Flyby Attacks before returning to their perches between attacks. They temporarily abandon targets inflicted with corporeal instability in favor of unaffected prey, unless no stable targets are available.","morale":"The chaos beasts fight to the death, at which time they return to their stony forms, appearing as broken statuary.","source":"AP 84, Pathfinder RPG Bestiary 2 54"},{"name":"Shendakut","cr":16,"xp":76800,"race":"androsphinx","gender":"Male","age_category":"Adult","classes":[{"class":"cleric of Set","level":6}],"alignment":"CE","size":"Large","type":"undead","sub_types":["augmented magical beast"],"templates_applied":"mummified","init":1,"senses":["darkvision 60 ft.","low-light vision"],"auras":["frightful presence (30 ft., DC 23, 1d6 rounds)"],"ac":31,"ac_touch":12,"ac_flat_footed":30,"ac_mods":"+2 deflection, +1 Dex, +19 natural, -1 size","hp":243,"hd":"13d8+6d8+158","hd_value":19,"fort":20,"ref":11,"will":15,"dr":"5/-","immunities":["undead traits"],"weaknesses":["vulnerable to acid"],"speed":[{"type":"fly","speed":50,"maneuverability":"clumsy"},{"type":"land","speed":30}],"melee":"2 claws +29 (3d6+13/19-20 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"burst of vengeance"},{"type":"channel negative energy","details":"10/day, DC 20, 3d6"},{"type":"dust stroke"},{"type":"pounce"},{"type":"rake","details":"2 claws +29, 3d6+13/19-20"},{"type":"roar","details":"DC 26"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"9/day","spells":[{"spell":"storm burst","details":"1d6+3 nonlethal"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":12,"spellsprepared_concentration":18,"spellsprepared":[{"spell_level":6,"spell_slots":4,"spells":[{"spell":"blade barrier"},{"spell":"control winds","type":"domain"},{"spell":"harm"},{"spell":"mass bull's strength"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"boneshatter"},{"spell":"greater command"},{"spell":"ice storm","type":"domain"},{"spell":"true seeing"},{"spell":"unholy ice"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"debilitating portent","count":2},{"spell":"fear","type":"domain"},{"spell":"freedom of movement"},{"spell":"unholy blight"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"bestow curse"},{"spell":"call lightning","type":"domain"},{"spell":"sands of time"},{"spell":"searing light","count":2},{"spell":"speak with dead"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"bull's strength"},{"spell":"fog cloud","type":"domain"},{"spell":"grace","count":3},{"spell":"hold person"},{"spell":"resist energy"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"bane"},{"spell":"cause fear","type":"domain"},{"spell":"command"},{"spell":"comprehend languages"},{"spell":"divine favor"},{"spell":"protection from good"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"read magic"}]}],"spelldomains":"Evil, Weather","strength":37,"dexterity":12,"intelligence":14,"wisdom":22,"charisma":25,"baseatk":17,"cmb":31,"cmd":44,"cmd_special":"48 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Combat Casting"},{"feat":"Flyby Attack"},{"feat":"Great Cleave"},{"feat":"Hover"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Natural Armor"},{"feat":"Improved Natural Attack (claw)"},{"feat":"Power Attack"},{"feat":"Spell Focus (necromancy)"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":2},{"skill":"Intimidate","value":17},{"skill":"Knowledge (religion)","value":23},{"skill":"Perception","value":32},{"skill":"Sense Motive","value":19},{"skill":"Survival","value":19}],"languages":["Ancient Osiriani","Auran","Sphinx"],"gear":"belt of giant strength +4, headband of alluring charisma +4, ring of protection +2, gold unholy symbol of Set (worth 50 gp), eye ointment (worth 250 gp), gold headpiece (worth 700 gp), scroll of storm of vengeance, flasks of unholy water (5)","before_combat":"When the stone block in area A9 begins to descend, Shendakut casts bull's strength on himself in case the PCs fail to solve his riddle or decide to fight.","during_combat":"Shendakut defends himself, or attacks first if he believes the PCs are stalling. He first uses greater command to make them flee or fall. If multiple PCs are in close proximity, he casts blade barrier in a ring shape around them so he can fly in from above, pluck them up, and drop them down the Windswept Shaft (area A4). Shendakut uses his most harmful spells on spellcasters and anyone capable of flight, so he can preserve his advantage against foes restricted to the ground.","morale":"Bound to service for eternity and ready to be destroyed to end his obligation to Hakotep, Shendakut fights to the death, as do the lightning elementals accompanying him.","source":"AP 84, Pathfinder RPG Bestiary 3 251, Pathfinder RPG Bestiary 4 196"},{"name":"Handmaiden Of Nailah","cr":9,"xp":6400,"race":"phantasm","age_category":"Adult","alignment":"CE","size":"Medium","type":"undead","sub_types":["incorporeal"],"templates_applied":"advanced","init":11,"senses":["darkvision 60 ft."],"auras":["desecrating aura (30 ft.)","unnatural aura (30 ft.)"],"ac":24,"ac_touch":22,"ac_flat_footed":17,"ac_mods":"+5 deflection, +7 Dex, +2 natural","hp":138,"hd":"12d8+84","hd_value":12,"fort":13,"ref":13,"will":14,"defensive_abilities":["incorporeal"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"incorporeal touch +19 (1d6+2 plus energy drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"energy drain","details":"1 level, DC 21"},{"type":"possession"}],"dexterity":25,"intelligence":19,"wisdom":19,"charisma":20,"baseatk":9,"cmb":16,"cmd":31,"feats":[{"feat":"Ability Focus (possession)"},{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Weapon Focus (incorporeal touch)"}],"skills":[{"skill":"Bluff","value":17},{"skill":"Fly","value":30},{"skill":"Intimidate","value":20},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":23},{"skill":"Sleight of Hand","value":19},{"skill":"Stealth","value":22},{"skill":"Survival","value":16}],"languages":["Abyssal","Ancient Osiriani"],"special_abilities":[{"type":"Desecrating Aura","kind":"Su","details":"The phantasm has a 30-foot-radius emanation equivalent to a desecrate spell centered on a shrine of evil power. Undead within this radius (including the phantasm) gain a +2 profane bonus on attack rolls, damage rolls, and saving throws; they also gain 2 hit points per Hit Die (these adjustments are included in the phantasm's stat block), and the save DC of channeled negative energy increases by 6. This aura can be negated by dispel evil, but a phantasm can reactivate the aura on its turn as a free action. A desecrating aura suppresses and is suppressed by consecrate or hallow; both effects are negated within any overlapping area of effect. When the phantasm is possessing a creature, its aura remains active, emanating from the host."},{"type":"Possession","kind":"Su","details":"Once per round, by making a successful incorporeal touch attack, a phantasm can merge its body with a creature on the Material Plane. This ability is similar to a magic jar spell, except that it doesn't require a receptacle. If the attack succeeds, the phantasm's body vanishes into the opponent's body. The target can resist the attack with a successful DC 23 Will save. A creature that successfully saves is immune to that phantasm's possession ability for 1 day. A possessing phantasm automatically imposes 1 negative level (from its energy drain ability) each round. A possessed creature can attempt a DC 23 Will save each round to force the phantasm out of its body. If the host succeeds, the phantasm is ejected and cannot attempt to possess the same host for 1 minute. If turned or subjected to a dismissal spell while possessing a host, the phantasm is likewise ejected. The save DCs are Charisma-based."}],"during_combat":"Upon their release, two handmaidens fly to aid their mistress with their desecrating auras and incorporeal touch attacks, while the others attempt to possess opponents who are farther away from Nailah. If a possessing phantasm imposes so many negative levels on a possessed creature that it dies, the phantasm immediately leaves the body and attempts to find a new host to possess.","morale":"Free to roam the entire Water Crypt, the handmaidens pursue any who flee the chamber, but they immediately return to aid Nailah if the battle goes poorly for her. The handmaidens fight until destroyed.","source":"AP 84, Tome of Horrors Complete 472, Pathfinder RPG Bestiary 294"},{"name":"Keshenepek","cr":16,"xp":76800,"race":"ghawwas div","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":6}],"alignment":"NE","size":"Large","type":"outsider","sub_types":["aquatic","div","evil","extraplanar"],"init":9,"senses":["darkvision 60 ft.","detect good","detect magic","see in darkness"],"ac":28,"ac_touch":12,"ac_flat_footed":23,"ac_mods":"+1 armor, +5 Dex, +15 natural, -2 rage, -1 size","hp":327,"hd":"14d10+6d12+206","hd_value":20,"fort":19,"ref":18,"will":14,"defensive_abilities":["evasion","improved uncanny dodge","rough hide","trap sense +2"],"dr":"10/cold iron and good","immunities":["fire","poison"],"resists":["acid 10","electricity 10"],"sr":21,"speed":[{"type":"land","speed":40},{"type":"swim","speed":80}],"melee":"+2 keen spear +34 (2d6+20/19-20/x3 plus poison), bite +28 (1d8+6/19-20), sting +26 (1d6+6 plus poison)","ranged":"+2 keen spear +27 (2d6+14/19-20/x3 plus poison)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"boiling sea","details":"DC 27"},{"type":"poison","details":"DC 27"},{"type":"rage","details":"22 rounds/day"},{"type":"rage powers","details":"no escape, quick reflexes, surprise accuracy +2"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"control water"},{"spell":"curse water"},{"spell":"deeper darkness"},{"spell":"dimension door"}]},{"frequency":"3/day","spells":[{"spell":"hallucinatory terrain"},{"spell":"quench"},{"spell":"stinking cloud"},{"spell":"summon","details":"1 pairaka 60%, level 6"}]}],"strength":34,"dexterity":20,"constitution":31,"intelligence":12,"wisdom":13,"charisma":18,"baseatk":20,"cmb":33,"cmd":46,"feats":[{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Greater Weapon Focus (bite)"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Critical (spear)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (spear)"}],"skills":[{"skill":"Bluff","value":27},{"skill":"Knowledge (geography)","value":18},{"skill":"Knowledge (planes)","value":24},{"skill":"Perception","value":24},{"skill":"Stealth","value":24},{"skill":"Survival","value":18},{"skill":"Swim","value":43}],"languages":["Abyssal","Ancient Osiriani","Aquan","Celestial","Infernal","telepathy 100 ft."],"sq":["amphibious","fast movement"],"gear":"+2 keen spear, belt of physical perfection +2, bracers of armor +1, hand of glory, ring of evasion, gold jewelry (worth 900 gp)","before_combat":"As soon as the stone blocks between areas B8 and B9 begin to descend, Keshenepek casts hallucinatory terrain to fill the chamber with illusory plant growth.   He then hides, readying to strike with his poisoned spear at the first intruder who approaches either the control pyramid or the scrivener's pillar.","during_combat":"Keshenepek gleefully engages the first opponent within reach, but prefers combat with martial adversaries if he spots them. After the bulk of the party has joined the battle, he alternates between using his boiling ability sea and melee strikes for the rest of the combat- unless he needs to use deeper darkness to catch a breather or reposition himself.","morale":"If reduced to 40 hit points or fewer, Keshenepek attempts to flee the chamber and then cast control water to lower the water directly beneath the tunnels back to area B8 by 24 feet. If he succeeds, the party will require another means to exit the chamber other than swimming. Once he reaches area B8, Keshenepek attempts to summon a pairaka, ordering it to delay the PCs. He then retreats to area  and allies with any mud elementals that remain. Keshenepek makes his last stand as the PCs exit the Water Crypt, fighting to the death.","base_statistics":"When not raging, Keshenepek's statistics are AC 30, touch 14, flat-footed 25; hp 287; Fort +17, Will +12; Melee +2 keen spear +32/+27/+22/+17 (2d6+17/19-20/x3 plus poison), bite +26 (1d8+5/19-20), sting +24 (1d6+5 plus poison); Ranged +2 keen spear +27 (2d6+12/19-20/x3 plus poison); Str 30, Con 27; CMB +31, CMD 46; Skills Swim +41.","source":"AP 84, Pathfinder RPG Bestiary 3 87"},{"name":"Earthcurse Scarab Swarm","cr":13,"xp":25600,"race":"scarab swarm","age_category":"Adult","alignment":"N","size":"Fine","type":"vermin","sub_types":["swarm"],"templates_applied":"advanced, fiendish","init":5,"senses":["darkvision 60 ft."],"ac":28,"ac_touch":23,"ac_flat_footed":23,"ac_mods":"+5 Dex, +5 natural, +8 size","hp":127,"hd":"17d8+51","hd_value":17,"fort":13,"ref":10,"will":10,"defensive_abilities":["swarm traits"],"dr":"10/good","immunities":["mind-affecting effects","weapon damage"],"resists":["cold 15","fire 15"],"sr":18,"speed":[{"type":"climb","speed":10},{"type":"fly","speed":20,"maneuverability":"clumsy"},{"type":"land","speed":30}],"melee":"swarm (4d6 plus cursed wound, disease, and distraction)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"consume"},{"type":"distraction","details":"DC 21"},{"type":"smite good","details":"1/day, +17 damage"}],"strength":1,"dexterity":20,"constitution":17,"wisdom":21,"charisma":2,"baseatk":12,"skills":[{"skill":"Climb","value":8},{"skill":"Fly","value":5},{"skill":"Perception","value":9}],"special_abilities":[{"type":"Consume","kind":"Ex","details":"An earthcurse scarab swarm can rapidly consume any creature it swarms over. Against helpless or nauseated targets, an earthcurse scarab swarm's swarm attack deals 8d6 points of damage."},{"type":"Cursed Wound","kind":"Ex","details":"The damage dealt by an earthcurse scarab swarm doesn't heal naturally and resists magical healing. A character attempting to use magical healing on a creature damaged by an earthcurse scarab swarm must succeed at a DC 24 caster level check, or the healing has no effect on the injured creature."},{"type":"Disease","kind":"Ex","details":"Filth fever: Swarm-injury; save Fortitude DC 21; onset 1d3 days; frequency 1/day; effect 1d3 Dex damage and 1d3 Con damage; cure 2 consecutive saves."}],"source":"AP 84, Pathfinder Adventure Path #79 89, Pathfinder RPG Bestiary 294"},{"name":"Hussef Daat","cr":13,"xp":25600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"magus","level":13}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"templates_applied":"pit-fiend-bound","init":10,"senses":["darkvision 60 ft.","see in darkness"],"ac":27,"ac_touch":19,"ac_flat_footed":20,"ac_mods":"+4 armor, +2 deflection, +6 Dex, +1 dodge, +4 natural","hp":114,"hd":"13d8+52","hd_value":13,"hp_mods":"regeneration 5 (good spells, good weapons)","fort":12,"ref":14,"will":9,"save_mods":"+4 vs. poison","resists":["fire 30"],"weaknesses":["contract bound"],"speed":[{"type":"land","speed":30}],"melee":"+1 Human bane short sword +17 (1d6+2/17-20) or mwk whip +16 (1d3+1 nonlethal)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"improved spell combat"},{"type":"spell combat","details":"-2 attack, +2 concentration"},{"type":"spellstrike"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"blasphemy"},{"spell":"summon","details":"or bone devil 100%, erinyes, bearded devil, 1 lemure, level 6"}]},{"frequency":"3/day","spells":[{"spell":"invisibility"},{"spell":"quickened fireball"}]}],"spellsprepared_caster":"magus","spellsprepared_caster_level":13,"spellsprepared_concentration":17,"spellsprepared":[{"spell_level":5,"spell_slots":1,"spells":[{"spell":"acidic spray"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"black tentacles"},{"spell":"ice storm"},{"spell":"phantasmal killer"},{"spell":"stoneskin"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"elemental aura"},{"spell":"lightning bolt"},{"spell":"locate weakness"},{"spell":"ray of exhaustion"},{"spell":"stinking cloud"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"blur"},{"spell":"cat's grace"},{"spell":"mirror image"},{"spell":"spider climb"},{"spell":"twisted space"},{"spell":"web"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"burning hands"},{"spell":"corrosive touch"},{"spell":"obscuring mist"},{"spell":"shield"},{"spell":"true strike","count":2}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"read magic"}]}],"strength":12,"dexterity":22,"constitution":14,"intelligence":18,"wisdom":8,"charisma":13,"baseatk":9,"cmb":10,"cmd":29,"feats":[{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Improved Critical (short sword)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Toughness"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (short sword)"}],"skills":[{"skill":"Intimidate","value":17},{"skill":"Knowledge (arcana)","value":20},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":12},{"skill":"Spellcraft","value":20},{"skill":"Stealth","value":19},{"skill":"Use Magic Device","value":17}],"languages":["Ancient Osiriani","Giant","Ignan","Infernal","Undercommon"],"sq":["arcane pool (10 points, +4)","fighter training (fighter level 6)","heavy armor proficiency","improved spell recall","knowledge pool","magus arcana (hasted assault, maximized magic, pool strike +5d6, spell shield)","medium armor proficiency"],"gear":"+2 leather armor, +1 Human bane short sword, mwk whip, belt of incredible dexterity +2, cloak of resistance +2, ring of protection +2, potions of cure moderate wounds (2)","before_combat":"Hussef cast cat's grace on himself just prior to entering the chamber.","during_combat":"Hussef casts quickened fireball and mirror image on the first round of combat. In the next round, he casts another quickened fireball and elemental aura (typically fire or acid). He then makes full attacks if possible, or casts evocation spells if entering melee is impractical.","morale":"If reduced to 50 hit points or fewer, Hussef summons a bone devil for backup, then casts invisibility. Unwilling to swallow his pride by backing down, he fights to the death.","source":"AP 84, Pathfinder RPG Bestiary 4 56, Pathfinder RPG Ultimate Magic 9"},{"name":"Eshen Theba","cr":17,"xp":102400,"race":"handmaiden devil","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":7}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["devil","evil","extraplanar","lawful"],"init":10,"senses":["darkvision 60 ft.","true seeing"],"ac":34,"ac_touch":16,"ac_flat_footed":28,"ac_mods":"+4 armor, +6 Dex, +14 natural","hp":282,"hd":"15d10+7d6+176","hd_value":22,"fort":19,"ref":17,"will":16,"save_mods":"+2 vs. poison","dr":"10/good","immunities":["fire","poison"],"resists":["acid 10","cold 10","electricity 20","fire 5"],"sr":25,"speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":40}],"melee":"2 claws +27 (2d8+9/19-20/x3), 2 tentacles +25 (1d8+4 plus grab)","space":"5 ft.","reach":"5 ft. (10 ft. with tentacle)","special_attacks":[{"type":"tentacle cage","details":"4d8+13 bludgeoning damage, AC 17, 28 hp"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"spider climb"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"alter self"},{"spell":"dispel good"},{"spell":"enthrall"},{"spell":"greater teleport","details":"self plus 1 entrapped creature and 50 lbs. of goods only"},{"spell":"persistent image"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"3 erinyes 65%, level 5"}]},{"frequency":"3/day","spells":[{"spell":"black tentacles"},{"spell":"charm monster"}]},{"frequency":"13/day","spells":[{"spell":"corrupting touch","details":"3 rounds"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":7,"spellsknown_concentration":17,"spellsknown":[{"spell_level":3,"spell_slots":6,"spells":[{"spell":"eruptive pustules"},{"spell":"stinking cloud"},{"spell":"suggestion"}]},{"spell_level":2,"spell_slots":9,"spells":[{"spell":"acid arrow"},{"spell":"scorching ray"},{"spell":"touch of idiocy"},{"spell":"web"}]},{"spell_level":1,"spell_slots":9,"spells":[{"spell":"charm person"},{"spell":"grease"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"protection from good"},{"spell":"ray of enfeeblement"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"bloodline":"infernal","strength":28,"dexterity":23,"constitution":27,"intelligence":24,"wisdom":22,"charisma":30,"baseatk":18,"cmb":27,"cmb_special":"+31 grapple, +29 trip","cmd":43,"cmd_special":"can't be tripped","feats":[{"feat":"Acrobatic Steps"},{"feat":"Combat Casting"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Deceitful"},{"feat":"Eschew Materials"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (tentacle)"},{"feat":"Improved Trip"},{"feat":"Multiattack"},{"feat":"Nimble Moves"},{"feat":"Spell Focus (enchantment)"},{"feat":"Strike Back"}],"skills":[{"skill":"Acrobatics","value":31,"special":"+4 when jumping"},{"skill":"Bluff","value":39},{"skill":"Diplomacy","value":35},{"skill":"Disguise","value":39},{"skill":"Fly","value":19},{"skill":"Intimidate","value":26},{"skill":"Knowledge (arcana)","value":32},{"skill":"Knowledge (planes)","value":32},{"skill":"Perception","value":31},{"skill":"Perform (sing)","value":35},{"skill":"Sense Motive","value":31},{"skill":"Spellcraft","value":32},{"skill":"Stealth","value":31}],"languages":["Ancient Osiriani","Celestial","Draconic","Infernal","telepathy 100 ft."],"sq":["agile grappler","bloodline arcana (+2 DC for charm spells)"],"gear":"headband of alluring charisma +6, major ring of electricity resistance, bejeweled skirt (worth 8,000 gp), potions of cure serious wounds (2), potion of undetectable alignment, scroll of displacement","before_combat":"If the PCs trigger the alarm in area C9, Eshen Theba is warned of their approach and uses alter self to take on her gruesome but clearly Human appearance. She then casts mage armor on herself and drinks her potion of undetectable alignment.","during_combat":"Eshen casts eruptive pustules, then concentrates physical attacks on those nearest to her. She uses black tentacles and her sorcerer spells against those who remain at a distance.","morale":"If Eshen is reduced to 100 hit points or fewer, she uses enthrall or charm monster to gain some respite from the PCs' assault. However, if the handmaiden devil has someone trapped in her tentacle cage, she uses greater teleport to reach area C3, where she can dispatch this lone foe or hold him for ransom. She then drinks a potion of invisibility before the others arrive. She makes her last stand there, fighting to the death.","source":"AP 84, Pathfinder RPG Bestiary 2 86"},{"name":"Inhetef","cr":16,"xp":76800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"inquisitor of Sekhmet","level":15}],"alignment":"CE","size":"Medium","type":"undead","sub_types":["augmented humanoid","human"],"templates_applied":"nosferatu","init":13,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":32,"ac_touch":17,"ac_flat_footed":29,"ac_mods":"+7 armor, +4 deflection, +3 Dex, +8 natural","hp":161,"hd":"15d8+90","hd_value":15,"hp_mods":"fast healing 5","fort":15,"ref":12,"will":19,"defensive_abilities":["channel resistance +4","stalwart"],"dr":"5/wood and piercing","immunities":["undead traits"],"resists":["cold 10","electricity 10","fire 10","sonic 10"],"weaknesses":["vampire weaknesses"],"speed":[{"type":"land","speed":20}],"melee":"+2 vicious battleaxe +19 (1d8+6/19-20/x3 plus 2d6), claw +10 (1d6+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain","details":"1d4 Con and 1d4 Wis"},{"type":"dominate","details":"DC 21"},{"type":"exploit weakness"},{"type":"greater bane","details":"+4d6, 15 rounds/day"},{"type":"telekinesis","details":"DC 21"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect alignment"}]},{"frequency":"9/day","spells":[{"spell":"fire bolt","details":"1d6+7 fire"}]},{"frequency":"15 rounds/day","spells":[{"spell":"discern lies"}]}],"spellsknown_caster":"inquisitor","spellsknown_caster_level":15,"spellsknown_concentration":19,"spellsknown":[{"spell_level":5,"spell_slots":4,"spells":[{"spell":"flame strike"},{"spell":"greater command"},{"spell":"mass inflict light wounds"},{"spell":"unwilling shield"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"divine power"},{"spell":"freedom of movement"},{"spell":"greater invisibility"},{"spell":"hold monster"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"burst of speed"},{"spell":"coordinated effort"},{"spell":"fester"},{"spell":"inflict serious wounds"},{"spell":"prayer"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"blistering invective"},{"spell":"death knell"},{"spell":"flames of the faithful"},{"spell":"inflict moderate wounds"},{"spell":"invisibility"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"bane"},{"spell":"command"},{"spell":"inflict light wounds"},{"spell":"protection from good"},{"spell":"shield of faith"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"sift"}]}],"spelldomains":"Fire","strength":18,"dexterity":16,"intelligence":12,"wisdom":22,"charisma":19,"baseatk":11,"cmb":15,"cmb_special":"+17 bull rush","cmd":33,"cmd_special":"35 vs. bull rush","feats":[{"feat":"Alertness","type":"bonus"},{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Coordinated Maneuvers"},{"feat":"Duck and Cover"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (battleaxe)"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes","type":"bonus"},{"feat":"Outflank"},{"feat":"Paired Opportunists"},{"feat":"Power Attack"},{"feat":"Skill FocusB (Intimidate)"},{"feat":"Skill FocusB (Perception)"},{"feat":"Spell Focus (necromancy)"},{"feat":"Swap Places"},{"feat":"Toughness"},{"feat":"Weapon Focus (battleaxe)"}],"skills":[{"skill":"Acrobatics","value":15},{"skill":"Climb","value":19},{"skill":"Intimidate","value":35},{"skill":"Knowledge (religion)","value":19},{"skill":"Perception","value":42},{"skill":"Sense Motive","value":43},{"skill":"Stealth","value":26},{"skill":"Use Magic Device","value":19}],"languages":["Ancient Osiriani","Infernal; telepathy 60 ft."],"sq":["cunning initiative","judgment (2, 5/day)","monster lore +6","solo tactics","spider climb","stern gaze","swarm form","track +7"],"gear":"+2 horn lamellar, +2 vicious battleaxe, cloak of resistance +2, shoes of the firewalker, gold unholy symbol of Sekhmet (worth 50 gp)","before_combat":"Inhetef casts freedom of movement and shield of faith on himself before combat.","during_combat":"Inhetef activates his destruction and justice judgments in the first round, and attempts to dominate one of his attackers to create another ally. In subsequent rounds, Inhetef casts divine power and flames of the faithful on his battleaxe, and enters melee combat after activating his greater bane ability. If surrounded, Inhetef casts unwilling shield on one of his enemies, and if given the opportunity, he uses telekinesis to push opponents into the lava pool. If a baykok's infused arrow paralyzes a PC, Inhetef must succeed at a DC 23 Will save to resist the overwhelming urge to rush to the helpless PC and drain her blood-he hasn't fed properly in ages. With his shoes of the firewalker and spider climb ability, Inhetef can move through most places in the Fire Crypt with little trouble.","morale":"Inhetef fights until reduced to 0 hit points, at which point he assumes bat swarm form and flees toward his sarcophagus in area D5. If the wall hasn't been broken down, he changes into a centipede swarm and crawls through tiny cracks in the wall nearby. Once in his sarcophagus, Inhetef is helpless for 1 hour until he regains 1 hit point.","source":"AP 84, Pathfinder RPG Bestiary 4 268, Pathfinder RPG Advanced Player's Guide 38"},{"name":"Mummified Akhumen","cr":10,"xp":9600,"race":"human","age_category":"Adult","classes":[{"class":"fighter","level":10}],"alignment":"LE","size":"Medium","type":"undead","sub_types":["human"],"templates_applied":"mummified","init":6,"senses":["darkvision 60 ft."],"auras":["frightful presence (30 ft., DC 12, 1d6 rounds)"],"ac":27,"ac_touch":13,"ac_flat_footed":24,"ac_mods":"+6 armor, +2 Dex, +1 dodge, +4 natural, +4 shield","hp":99,"hd":"10d10+40","hd_value":10,"fort":9,"ref":7,"will":4,"save_mods":"Will: +3 vs. fear","defensive_abilities":["bravery +3"],"dr":"5/-","immunities":["undead traits"],"weaknesses":["sonic"],"speed":[{"type":"land","speed":20}],"melee":"+1 menacing khopesh +21 (1d8+11/17-20) or slam +16 (1d6+9)","ranged":"mwk longbow +14 (1d8+1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burst of vengeance"},{"type":"dust stroke"},{"type":"weapon training","details":"heavy blades +2, bows +1"}],"strength":22,"dexterity":14,"intelligence":8,"wisdom":12,"charisma":14,"baseatk":10,"cmb":16,"cmd":29,"feats":[{"feat":"Dodge"},{"feat":"Greater Weapon Focus (khopesh)"},{"feat":"Improved Critical (khopesh)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Shield Focus"},{"feat":"Toughness"},{"feat":"Weapon Focus (khopesh)"},{"feat":"Weapon Specialization (khopesh)"}],"skills":[{"skill":"Intimidate","value":15},{"skill":"Perception","value":11},{"skill":"Stealth","value":4}],"languages":["Ancient Osiriani"],"sq":["armor training 2"],"gear":"+1 horn lamellar, +1 heavy wooden shield, +1 menacing khopesh, mwk longbow with 15 arrows","during_combat":"All of the Akhumen unleash their arrows on the first round of combat. On subsequent rounds, three of the soldiers hang back, continuing to fire arrows at foes while the remaining five close ranks and charge into melee, taking flanking positions to take advantage of their menacing khopeshes. They immediately use their burst of vengeance ability for 2 consecutive rounds, hoping to disable their opponents so they can kill foes with slam attacks.","morale":"Loyal to Hakotep even in undeath, the Akhumen fight until destroyed.","source":"AP 84, Pathfinder RPG Bestiary 4 196"},{"name":"Dark Plasma Ooze","cr":16,"xp":76800,"race":"plasma ooze","age_category":"Adult","alignment":"N","size":"Huge","type":"ooze","init":7,"senses":["blindsight 60 ft."],"auras":["magnetic pulse (30 ft.)"],"ac":12,"ac_touch":12,"ac_flat_footed":8,"ac_mods":"+3 Dex, +1 dodge, -2 size","hp":225,"hd":"18d8+144","hd_value":18,"fort":15,"ref":11,"will":1,"defensive_abilities":["split (slashing or sonic, 112 hp)"],"dr":"15/-","immunities":["acid","bludgeoning and piercing damage","electricity","ooze traits"],"resists":["fire 30"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"slam +23 (4d6+16 plus 4d6 cold, 4d6 electricity, and grab)","ranged":"1d4 plasma arc +15 touch (4d6 cold plus 4d6 electricity)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"constrict","details":"4d6+16 plus 4d6 cold and 4d6 electricity"},{"type":"engulf","details":"DC 30, 4d6 cold plus 4d6 electricity"}],"strength":32,"dexterity":16,"constitution":24,"intelligence":3,"wisdom":1,"charisma":1,"baseatk":13,"cmb":26,"cmb_special":"+30 grapple","cmd":40,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Stealth)"},{"feat":"Toughness"},{"feat":"Weapon Focus (plasma arc)"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Fly","value":28},{"skill":"Stealth","value":6}],"sq":["compression","no breath"],"special_abilities":[{"type":"Plasma Arc","kind":"Su","details":"A dark plasma ooze's plasma arcs function the same as a normal plasma ooze's rays, but can arc around corners (ignoring line of sight restrictions and negating concealment modifiers) if the target wears any metal."}],"during_combat":"When one or more intruders possessing metallic belongings comes within 15 ft. of the chamber, the ooze starts using its magnetic pulse ability, and fires plasma arcs from its hiding place. It keeps using its ranged attacks until at least one creature is in the room below it. The ooze then switches to melee attacks with the intention of engulfing its prey. If the PCs retreat from the beast, it descends from its perch and starts making its way down the hall toward the party, continuing to make ranged attacks until it is close enough to engage the PCs in melee combat.","morale":"If reduced to 40 hit points or fewer, the ooze attempts to retreat, though its options are limited (it can't open the secret door to area E9, nor can it open the stone block to area E12.)","source":"AP 84, Pathfinder RPG Bestiary 3 220"},{"name":"Khenpathes","cr":15,"xp":51200,"race":"bonepowder ghoul","gender":"Male","age_category":"Adult","alignment":"NE","size":"Small","type":"undead","init":9,"senses":["darkvision 60 ft."],"ac":17,"ac_touch":17,"ac_flat_footed":11,"ac_mods":"+5 Dex, +1 dodge, +1 size","hp":178,"hd":"17d8+102","hd_value":17,"fort":11,"ref":12,"will":12,"defensive_abilities":["amorphous","channel resistance +4"],"immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"melee":"bite +18 (1d6 plus 1d3 Str and paralysis)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"coalesce"},{"type":"gravedust"},{"type":"whirlwind of bones"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":23,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"chill touch"},{"spell":"deeper darkness"},{"spell":"dispel magic"},{"spell":"ray of enfeeblement"}]},{"frequency":"1/day","spells":[{"spell":"energy drain"}]},{"frequency":"3/day","spells":[{"spell":"blindness/deafness"},{"spell":"empowered enervation"}]}],"strength":10,"dexterity":20,"intelligence":19,"wisdom":15,"charisma":22,"baseatk":12,"cmb":16,"cmd":27,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Dodge"},{"feat":"Empower Spell-Like Ability (enervation)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Stealthy"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Climb","value":15},{"skill":"Diplomacy","value":13},{"skill":"Disguise","value":15},{"skill":"Escape Artist","value":18},{"skill":"Fly","value":19},{"skill":"Intimidate","value":19},{"skill":"Knowledge (arcana)","value":20},{"skill":"Knowledge (dungeoneering)","value":19},{"skill":"Knowledge (history)","value":15},{"skill":"Knowledge (religion)","value":20},{"skill":"Perception","value":22},{"skill":"Stealth","value":30}],"languages":["Ancient Osiriani","Draconic","Dwarven","Undercommon"],"sq":["dusty form","hide in plain sight"],"special_abilities":[{"type":"Coalesce","kind":"Su","details":"Once a bonepowder ghoul has drained 5 or more points of Strength or has inflicted level drain via enervation, it can assume the form of a Small humanoid as a free action. It can maintain this form for no more than 10 minutes before it collapses back into its dusty form. When coalesced, a bonepowder ghoul can manipulate objects and make physical attacks."},{"type":"Dusty Form","kind":"Su","details":"A bonepowder ghoul's normal form is a pile of powdered bone. In this form, it can't make bite attacks, nor can it manipulate objects, but it can cast spells and use spell-like abilities and its other special attacks. The damage it takes from physical attacks is reduced by 50% while it's in its dusty form."},{"type":"Gravedust","kind":"Su","details":"As a standard action once every 3 rounds, a bonepowder ghoul can project a 40-foot cone of grave dust. All creatures in the area must succeed at a DC 24 Fortitude save or take 1d6 points of Strength damage and become infected with ghoul fever. The bonepowder ghoul gains a temporary bonus to Strength equal to the total points of Strength damage dealt. This bonus lasts for 10 minutes per 5 ability points drained or until the next time the ghoul projects a cone of gravedust. The save DC is Charisma-based."},{"type":"Paralysis","kind":"Su","details":"Those hit by a bonepowder ghoul's physical attacks must succeed at a DC 24 Fortitude save or become paralyzed for 1d4+1 rounds. The save DC is Charisma-based."},{"type":"Whirlwind of Bones","kind":"Su","details":"Once per day as a standard action, a bonepowder ghoul in dusty form can create a small cyclone of whirling teeth and bone fragments. All living creatures within 20 ft. of a bonepowder ghoul's whirlwind take 2d12 points of slashing damage (no save) and 1d6 points of Strength drain (Fortitude DC 24 negates). The save DC is Charisma-based."}],"during_combat":"Khenpathes starts his assault in dusty form by using his whirlwind of bones ability, then expels gravedust into area E17, followed by empowered enervation rays. He continues to target foes with his spell-like abilities, alternating his attacks with more gravedust and empowered enervation.","morale":"Zealously committed to serving Hakotep, Khenpathes fights until utterly destroyed.","source":"AP 84, Midgard Bestiary 51"},{"name":"General Tawaret","cr":17,"xp":102400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":16}],"alignment":"LE","size":"Medium","type":"undead","sub_types":["augmented humanoid","human"],"templates_applied":"graveknight","init":8,"senses":["darkvision 60 ft."],"auras":["sacrilegious aura (30 ft., DC 23)"],"ac":30,"ac_touch":16,"ac_flat_footed":26,"ac_mods":"+10 armor, +2 deflection, +4 Dex, +4 natural","hp":204,"hd":"16d10+112","hd_value":16,"fort":17,"ref":9,"will":8,"save_mods":"Will: +4 vs. fear","defensive_abilities":["bravery +4","channel resistance +4","rejuvenation"],"dr":"10/magic","immunities":["cold","electricity","undead traits"],"sr":28,"speed":[{"type":"land","speed":30}],"melee":"+1 keen greatsword +25 (2d6+12 plus 4d6 cold/17-20) or slam +22 (1d4+9)","ranged":"+1 speed composite longbow +26 (1d8+14 plus 4d6 cold/19-20/x3) or Rapid Shot +24 (1d8+14 plus 4d6 cold/19-20/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel destruction","details":"4d6 cold"},{"type":"devastating   blast","details":"10d6 cold, DC 23"},{"type":"undead mastery","details":"DC 23"},{"type":"weapon training","details":"bows +3, heavy blades +2, spears +1"}],"strength":22,"dexterity":18,"intelligence":12,"wisdom":16,"charisma":20,"baseatk":16,"cmb":22,"cmd":38,"feats":[{"feat":"Critical Focus"},{"feat":"Critical Mastery"},{"feat":"Deadly Aim"},{"feat":"Great Fortitude"},{"feat":"Greater Weapon Focus (composite longbow)"},{"feat":"Greater Weapon Specialization (composite longbow)"},{"feat":"Improved Critical (composite longbow)"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Improved Vital Strike"},{"feat":"Manyshot"},{"feat":"Mounted Combat","type":"bonus"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Ride-By Attack","type":"bonus"},{"feat":"Sickening Critical"},{"feat":"Staggering Critical"},{"feat":"Toughness","type":"bonus"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (composite longbow)"},{"feat":"Weapon Specialization (composite longbow)"}],"skills":[{"skill":"Intimidate","value":32},{"skill":"Perception","value":27},{"skill":"Profession (driver)","value":22},{"skill":"Ride","value":30}],"languages":["Ancient Osiriani","Tekritanin"],"sq":["armor training 4","phantom mount","ruinous revivification (cold)"],"gear":"+1 full plate, +1 keen greatsword, +1 speed composite longbow (+6 Str), belt of incredible dexterity +2, chariot of the conqueror, ring of protection +2, +1 flaming arrows (8), +1 frost arrows (15), +1 shock arrows (8), sizzling arrows (2), javelins of lightning (2), potions of inflict serious wounds (2)","during_combat":"Tawaret keeps her chariot of the conqueror in constant motion, firing arrows from the chariot as it careens through the air from one end of the chamber to the other. She switches targets frequently, and varies which magic arrows she uses to keep her enemies guessing. She makes frequent use of Manyshot and Rapid Shot to pepper foes with as many arrows as possible. She saves her javelins of lightning until she runs out of arrows, then resorts to using her greatsword with Ride-By Attacks.","morale":"General Tawaret pursues retreating PCs and fights until she is slain. If her armor isn't destroyed, she hunts down the party after she rejuvenates.","source":"AP 84, Pathfinder RPG Bestiary 3 138"},{"name":"Shield Of Hakotep","cr":13,"xp":25600,"race":"clay golem","age_category":"Adult","alignment":"N","size":"Large","type":"construct","templates_applied":"advanced, shield guardian","init":1,"senses":["darkvision 60 ft.","low-light vision"],"ac":28,"ac_touch":10,"ac_flat_footed":27,"ac_mods":"+1 Dex, +18 natural, -1 size","hp":127,"hd":"13d10+56","hd_value":13,"hp_mods":"fast healing 5","fort":4,"ref":5,"will":6,"dr":"10/adamantine and bludgeoning","immunities":["construct traits","magic"],"speed":[{"type":"land","speed":20}],"melee":"2 slams +21 (2d10+9 plus cursed wound)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"berserk"},{"type":"haste"}],"spell_like_abilities_caster_level":18,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"shield other"},{"spell":"spell storing","details":"boneshatter"}]}],"strength":28,"dexterity":13,"wisdom":15,"charisma":5,"baseatk":13,"cmb":23,"cmd":34,"sq":["controlled","find master","guard"],"during_combat":"Two of the golems stand adjacent Hakotep, using their guard ability to defend him, while the other two advance upon foes, activating their haste ability as soon as possible. If hard pressed, Hakotep commands the golems to cast their stored boneshatter spells.","morale":"If one of the golems guarding Hakotep falls, he orders another to replace it, if possible. The Shields of Hakotep fight until destroyed.","source":"AP 84, Pathfinder RPG Bestiary 158, 159, 294"}];
